// EngControl v1.3 — Missões Bônus e dados operacionais
'use strict';
const BONUS_MISSIONS={
  crane:{
    id:'crane',triggerLevel:10,title:'Painel de comando do guindaste',icon:'🏗️',reward:2600,
    related:['nr10','nr35','epi-ca','planejamento'],
    theory:[
      `<div class='theory-box'><h3>Intervenção elétrica em altura: planejar antes de subir</h3><p>Uma manutenção em painel de comando instalado em altura exige integrar <b>planejamento da OS, análise de risco, competência da equipe, controle de energias, acesso seguro, EPI/EPC, ferramentas e materiais</b>. O objetivo da missão é demonstrar que segurança e disponibilidade precisam ser planejadas em conjunto.</p><p><b>NR-10:</b> serviços em instalações elétricas exigem medidas de controle, procedimentos, trabalhadores autorizados/capacitados conforme o caso e organização do trabalho. <b>NR-35:</b> atividades com risco de queda em altura exigem planejamento, análise de risco e medidas de prevenção compatíveis. O jogo é educacional e não substitui capacitação, autorização, procedimentos internos ou consulta à versão vigente das NRs.</p></div>`,
      `<div class='theory-grid'><div class='concept-card'><h3>EPI, EPC e CA</h3><p>O EPI deve ser adequado ao risco, estar em condição de uso e possuir <b>Certificado de Aprovação (CA)</b> aplicável. A validade do CA e a condição do equipamento devem ser verificadas conforme os procedimentos da organização e consulta oficial. CA válido não substitui inspeção de conservação, ajuste e uso correto.</p></div><div class='concept-card'><h3>Fluxo de materiais</h3><p>Antes de comprar, consulte o estoque. Uma <b>Requisição de Material</b> reserva itens internos para a OS. Se um recurso essencial não estiver disponível, a intervenção deve ser suspensa/reprogramada e uma <b>Ordem de Compra</b> pode ser aberta, desde que técnica e financeiramente justificável.</p></div></div><div class='keyline'><b>Regra da missão:</b> segurança não pode ser compensada por prazo ou orçamento. Sem recurso obrigatório, a OS não deve ser liberada.</div>`
    ]
  },
  quality:{id:'quality',triggerLevel:18,title:'Falha reincidente na fonte de potência',icon:'🧭',reward:2200,related:['ishikawa','pdca','5w2h','qualidade'],theory:[
    `<div class='theory-box'><h3>Da falha recorrente à causa verificável</h3><p>Uma ocorrência repetitiva exige mais que trocar o componente que falhou. O <b>Diagrama de Ishikawa</b> ajuda a organizar hipóteses de causa; o <b>PDCA</b> estrutura o ciclo de melhoria; e o <b>5W2H</b> transforma uma ação escolhida em plano executável, com responsável, prazo, método e custo.</p></div>`,
    `<div class='theory-grid'><div class='concept-card'><h3>Ishikawa</h3><p>Organize hipóteses em categorias coerentes e procure evidências. Uma hipótese bem escrita ainda não é uma causa comprovada.</p></div><div class='concept-card'><h3>PDCA + 5W2H</h3><p>Planeje com base no problema, execute controladamente, verifique dados e padronize/corrija. No plano 5W2H, <i>How much</i> deve caber no fundo disponível e representar custo estimado realista.</p></div></div>`
  ]},
  fiveS:{id:'fiveS',triggerLevel:24,title:'Auditoria surpresa na oficina',icon:'🧹',reward:1700,related:['5s','qualidade'],theory:[
    `<div class='theory-box'><h3>5S como condição para manutenção confiável</h3><p>5S não é apenas estética. Separar o necessário, organizar locais, manter limpeza, padronizar e sustentar disciplina reduz tempo de procura, mistura de peças, contaminação e riscos. Nesta missão, a oficina será auditada sem aviso prévio.</p></div>`,
    `<div class='theory-grid'><div class='concept-card'><h3>Observe evidências</h3><p>Ferramenta sem identificação, sucata misturada com peças boas, derramamentos, corredores obstruídos e padrões não cumpridos são indícios diferentes e exigem ações adequadas.</p></div><div class='concept-card'><h3>Auditoria</h3><p>Uma auditoria útil registra evidência, responsável e ação. Evite “arrumar para a foto”; a melhoria precisa permanecer no processo.</p></div></div>`
  ]},
  machine:{id:'machine',triggerLevel:41,title:'Intervenção em máquina automatizada',icon:'🏭',reward:2800,related:['nr12','nr10','planejamento'],theory:[
    `<div class='theory-box'><h3>Máquinas e equipamentos: manutenção com segurança integrada</h3><p>A NR-12 estabelece referências de segurança para máquinas e equipamentos ao longo do ciclo de vida. Em manutenção, o planejamento deve considerar acesso, energias perigosas, proteções, dispositivos de segurança, condições de retorno à operação e documentação aplicável.</p></div>`,
    `<div class='theory-grid'><div class='concept-card'><h3>Antes de intervir</h3><p>Defina condição segura, controle de energias, bloqueios, área, equipe e teste. Não improvise retirada de proteções nem neutralize dispositivos para “ganhar tempo”.</p></div><div class='concept-card'><h3>Retorno à operação</h3><p>Após a manutenção, proteções e dispositivos devem ser restabelecidos e testados conforme procedimento antes da liberação do equipamento.</p></div></div>`
  ]},
  predictive:{id:'predictive',triggerLevel:55,title:'Anomalia antes da falha',icon:'📈',reward:3000,related:['preditiva','indicadores','dadosiot'],theory:[
    `<div class='theory-box'><h3>Uma boa intervenção acontece na janela correta</h3><p>Dados de condição podem mostrar degradação antes da perda de função. O desafio é combinar tendência, criticidade, disponibilidade de equipe/material, custo e janela operacional para decidir se deve monitorar, programar ou intervir.</p></div>`,
    `<div class='theory-grid'><div class='concept-card'><h3>Evite dois extremos</h3><p>Intervir cedo demais pode desperdiçar vida útil; tarde demais pode transformar uma oportunidade planejada em corretiva emergencial.</p></div><div class='concept-card'><h3>Controle</h3><p>Registre a decisão, o limite adotado e a próxima verificação. Dados sem plano de ação não reduzem risco.</p></div></div>`
  ]}
};
