LEVELS[60]={"phase":11,"title":"Realidade Aumentada","subtitle":"Informação no contexto","lead":"RA pode sobrepor informações digitais ao ativo físico para identificação, instrução e apoio à manutenção.","theory":["<div class='theory-box'><h3>Realidade Aumentada</h3><p>RA pode sobrepor informações digitais ao ativo físico para identificação, instrução e apoio à manutenção.</p><p>A informação exibida precisa ser atual, relevante, segura e vinculada corretamente ao equipamento.</p></div><div class='theory-grid'><div class='concept-card'><h3>Aplicação no PCM</h3><p>O objetivo é transformar informação técnica em uma decisão planejada, rastreável e coerente com segurança, qualidade, disponibilidade e custo.</p></div><div class='concept-card'><h3>Boa prática</h3><p>Registre fonte dos dados, critérios utilizados, responsáveis e resultado. A decisão deve poder ser compreendida por outra pessoa da equipe.</p></div></div><div class='keyline'><b>Ideia-chave:</b> A informação exibida precisa ser atual, relevante, segura e vinculada corretamente ao equipamento.</div>","<div class='real-box'><h3>Contexto de vida real</h3><p>Um tablet identifica EQ-024 e exibe temperatura, última preventiva, OS abertas e disponibilidade.</p></div><div class='theory-grid'><div class='concept-card'><h3>Antes de decidir</h3><ul><li>Verifique a qualidade das informações.</li><li>Considere risco e criticidade.</li><li>Confirme recursos e limitações.</li><li>Registre a justificativa técnica.</li></ul></div><div class='concept-card'><h3>Depois de decidir</h3><p>Acompanhe o resultado e compare-o com o esperado. Planejamento e controle formam um ciclo.</p></div></div><div class='warning-line'><b>Na atividade:</b> cinco decisões serão registradas; respostas incorretas não bloqueiam o avanço e recebem feedback.</div>"],"questions":[{"q":"Qual vantagem da RA nesse cenário?","c":"Um tablet identifica EQ-024 e exibe temperatura, última preventiva, OS abertas e disponibilidade.","a":[["Apresentar dados e instruções no contexto do ativo, reduzindo busca manual de informação.",1,"Contextualização pode agilizar a tarefa.",{"rel":2}],["Decidir apenas pela urgência percebida, sem consultar critérios técnicos ou registros.",0,"Urgência percebida isoladamente não substitui análise técnica, risco e rastreabilidade.",{"rel":-2}],["Executar a primeira ação disponível e registrar somente depois.",0,"Planejamento deve anteceder a execução quando há tempo e condições para isso.",{"rel":-2}],["Usar a mesma solução para todos os equipamentos, independentemente do contexto.",0,"Criticidade, regime de uso, tecnologia e histórico podem exigir decisões diferentes.",{"rel":-2}],["Ignorar os dados que não confirmam a hipótese inicial.",0,"Descartar evidências contraditórias aumenta o risco de uma conclusão incorreta.",{"rel":-2}]]},{"q":"RA substitui procedimentos de segurança?","c":"Um tablet identifica EQ-024 e exibe temperatura, última preventiva, OS abertas e disponibilidade.","a":[["Não; ela é ferramenta de apoio e não elimina requisitos técnicos e de segurança.",1,"Tecnologia não substitui controle de risco.",{"rel":2}],["Decidir apenas pela urgência percebida, sem consultar critérios técnicos ou registros.",0,"Urgência percebida isoladamente não substitui análise técnica, risco e rastreabilidade.",{"rel":-2}],["Executar a primeira ação disponível e registrar somente depois.",0,"Planejamento deve anteceder a execução quando há tempo e condições para isso.",{"rel":-2}],["Usar a mesma solução para todos os equipamentos, independentemente do contexto.",0,"Criticidade, regime de uso, tecnologia e histórico podem exigir decisões diferentes.",{"rel":-2}],["Ignorar os dados que não confirmam a hipótese inicial.",0,"Descartar evidências contraditórias aumenta o risco de uma conclusão incorreta.",{"rel":-2}]]},{"q":"Como evitar mostrar dados do ativo errado?","c":"Um tablet identifica EQ-024 e exibe temperatura, última preventiva, OS abertas e disponibilidade.","a":[["Usar identificação confiável e validar associação entre marcador/tag e cadastro do equipamento.",1,"Vínculo incorreto pode causar decisão errada.",{"rel":2}],["Decidir apenas pela urgência percebida, sem consultar critérios técnicos ou registros.",0,"Urgência percebida isoladamente não substitui análise técnica, risco e rastreabilidade.",{"rel":-2}],["Executar a primeira ação disponível e registrar somente depois.",0,"Planejamento deve anteceder a execução quando há tempo e condições para isso.",{"rel":-2}],["Usar a mesma solução para todos os equipamentos, independentemente do contexto.",0,"Criticidade, regime de uso, tecnologia e histórico podem exigir decisões diferentes.",{"rel":-2}],["Ignorar os dados que não confirmam a hipótese inicial.",0,"Descartar evidências contraditórias aumenta o risco de uma conclusão incorreta.",{"rel":-2}]]},{"q":"A temperatura exibida é de ontem. O que a interface deve fazer?","c":"Um tablet identifica EQ-024 e exibe temperatura, última preventiva, OS abertas e disponibilidade.","a":[["Indicar claramente data/hora e condição de atualização do dado.",1,"Atualidade é parte da qualidade da informação.",{"rel":2}],["Decidir apenas pela urgência percebida, sem consultar critérios técnicos ou registros.",0,"Urgência percebida isoladamente não substitui análise técnica, risco e rastreabilidade.",{"rel":-2}],["Executar a primeira ação disponível e registrar somente depois.",0,"Planejamento deve anteceder a execução quando há tempo e condições para isso.",{"rel":-2}],["Usar a mesma solução para todos os equipamentos, independentemente do contexto.",0,"Criticidade, regime de uso, tecnologia e histórico podem exigir decisões diferentes.",{"rel":-2}],["Ignorar os dados que não confirmam a hipótese inicial.",0,"Descartar evidências contraditórias aumenta o risco de uma conclusão incorreta.",{"rel":-2}]]},{"q":"Que informação é mais útil em campo?","c":"Um tablet identifica EQ-024 e exibe temperatura, última preventiva, OS abertas e disponibilidade.","a":[["Dados relevantes à tarefa, histórico essencial, riscos, procedimento e situação atual, sem sobrecarregar a interface.",1,"RA deve apoiar decisão, não distrair.",{"rel":2}],["Decidir apenas pela urgência percebida, sem consultar critérios técnicos ou registros.",0,"Urgência percebida isoladamente não substitui análise técnica, risco e rastreabilidade.",{"rel":-2}],["Executar a primeira ação disponível e registrar somente depois.",0,"Planejamento deve anteceder a execução quando há tempo e condições para isso.",{"rel":-2}],["Usar a mesma solução para todos os equipamentos, independentemente do contexto.",0,"Criticidade, regime de uso, tecnologia e histórico podem exigir decisões diferentes.",{"rel":-2}],["Ignorar os dados que não confirmam a hipótese inicial.",0,"Descartar evidências contraditórias aumenta o risco de uma conclusão incorreta.",{"rel":-2}]]}]};
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}function chk(s){return hash(s).toString(36).toUpperCase().padStart(7,'0')}function enc(s){return btoa(unescape(encodeURIComponent(s))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}function dec(s){s=s.replace(/-/g,'+').replace(/_/g,'/');while(s.length%4)s+='=';return decodeURIComponent(escape(atob(s)))}function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function fresh(name,avatar){let id='ENG-'+String(hash(name+Date.now())%100000).padStart(5,'0');let x={v:'1.3',name,avatar,id,role:'Assistente de Manutenção',globalScore:0,best:{},completed:[],unlocked:[1,6,11,16,25,29,36,42,49,53,57],correct:0,total:0,errors:0,availability:98,reliability:92,safety:100,budget:25000,lastCode:'',readContent:[],documents:{reports:{}}};ensureOperations(x);return x}
function cloneData(v){return JSON.parse(JSON.stringify(v))}
function ensureOperations(x){if(!x)return;x.operations=x.operations||{};let o=x.operations;o.stock=o.stock||cloneData(DEFAULT_STOCK);o.team=o.team||cloneData(DEFAULT_TEAM);o.assets=o.assets||cloneData(DEFAULT_ASSETS);o.os=o.os||[];o.purchaseOrders=o.purchaseOrders||[];o.materialRequests=o.materialRequests||[];o.ledger=o.ledger||[{date:new Date().toISOString(),description:'Fundo inicial de manutenção',amount:25000,balance:x.budget??25000,type:'initial'}];o.missions=o.missions||{};o.pendingBonus=o.pendingBonus||[];o.notifications=o.notifications||[];o.audits=o.audits||[];o.step=o.step||0;return o}
function finance(description,amount,type='operation'){ensureOperations(state);let before=state.budget;state.budget=Math.max(0,Math.round((state.budget+amount)*100)/100);state.operations.ledger.push({date:new Date().toISOString(),description,amount,balance:state.budget,type});save();return{before,after:state.budget}}
function missionState(id){ensureOperations(state);return state.operations.missions[id]||(state.operations.missions[id]={status:'not-started',attempts:0})}
function openOS(id){ensureOperations(state);return state.operations.os.find(x=>x.id===id)}
function stockItem(id){ensureOperations(state);return state.operations.stock.find(x=>x.id===id)}
function addOS(missionId,title,assetId){ensureOperations(state);let m=missionState(missionId);if(m.osId)return openOS(m.osId);let id='OS-BON-'+String(state.operations.os.length+1).padStart(3,'0');let os={id,missionId,title,assetId,status:'ABERTA',created:new Date().toISOString(),history:[{date:new Date().toISOString(),event:'OS aberta pela ocorrência bônus'}],requirements:[],materialRequest:null,purchaseOrder:null};state.operations.os.push(os);m.osId=id;save();return os}
function osStatus(os,status,note){os.status=status;os.history.push({date:new Date().toISOString(),event:note||status});save()}
function addNotification(text){ensureOperations(state);state.operations.notifications.push({date:new Date().toISOString(),text,seen:false});save()}
function advanceOperationalTime(){if(!state)return;ensureOperations(state);state.operations.step++;let arrived=[];state.operations.purchaseOrders.filter(p=>p.status==='EXPEDIDA').forEach(p=>{p.leadSteps=Math.max(0,(p.leadSteps??2)-1);if(p.leadSteps===0){p.status='RECEBIDA';p.items.forEach(it=>{let s=stockItem(it.id);if(s)s.qty+=it.qty;else state.operations.stock.push({id:it.id,name:it.name,type:'adquirido',qty:it.qty,min:0,cost:it.unit});});let os=openOS(p.osId);if(os&&os.status.includes('AGUARDANDO'))osStatus(os,'PRONTA PARA RETOMADA','Material da '+p.id+' recebido; OS liberada para retomada');arrived.push(p.id+(os?' / '+os.id:''));}});if(arrived.length)addNotification('📦 Material recebido: '+arrived.join(', ')+'. Consulte o Centro Operacional.');save()}
function consumeOrReserve(ids,os){let missing=[];ids.forEach(id=>{let s=stockItem(id);if(!s||s.qty<1)missing.push(id);else if(['consumível','sobressalente'].includes(s.type)){s.qty-=1}});if(os)os.history.push({date:new Date().toISOString(),event:'Requisição de materiais processada: '+ids.join(', ')});save();return missing}
function migrateState(x){if(!x)return x;x.v='1.3';ensureOperations(x);x.best=x.best||{};x.completed=x.completed||[];x.unlocked=x.unlocked||[1];if(!x.unlocked.includes(1))x.unlocked.push(1);if(!x.unlocked.includes(6))x.unlocked.push(6);if(!x.unlocked.includes(16))x.unlocked.push(16);if(!x.unlocked.includes(25))x.unlocked.push(25);if(!x.unlocked.includes(29))x.unlocked.push(29);if(!x.unlocked.includes(36))x.unlocked.push(36);if(!x.unlocked.includes(57))x.unlocked.push(57);if(!x.unlocked.includes(53))x.unlocked.push(53);if(!x.unlocked.includes(49))x.unlocked.push(49);if(!x.unlocked.includes(42))x.unlocked.push(42);if(!x.unlocked.includes(11))x.unlocked.push(11);x.correct=x.correct||0;x.total=x.total||0;x.errors=x.errors||0;x.availability=x.availability??98;x.reliability=x.reliability??92;x.safety=x.safety??100;x.budget=x.budget??25000;x.readContent=x.readContent||[];x.documents=x.documents||{};x.documents.reports=x.documents.reports||{};if(!x.avatar&&x.gender&&AVATARS.some(a=>a[0]===x.gender))x.avatar=x.gender;return x}
function save(){if(state)localStorage.setItem(KEY,JSON.stringify(state));hud()}function show(id){document.querySelectorAll('.screen').forEach(x=>x.classList.remove('active'));$(id).classList.add('active');el.hud.style.display=(!state||['start','profile','library','contentDetail','practiceHub','practiceGame'].includes(id))?'none':'grid';window.scrollTo(0,0);hud()}function accuracy(){return state&&state.total?Math.round(state.correct/state.total*100):0}function hud(){if(!state)return;el.hudScore.textContent=state.globalScore.toLocaleString('pt-BR');el.hudAccuracy.textContent=accuracy()+'%';el.hudAvail.textContent=state.availability+'%';el.hudSafety.textContent=state.safety+'%';if(el.hudBudget)el.hudBudget.textContent='R$ '+Number(state.budget).toLocaleString('pt-BR')}
function campaignEntry(){if(state){showHome();return}try{let s=localStorage.getItem(KEY);if(s){state=migrateState(JSON.parse(s));showHome();return}}catch(e){}show('profile')}
