function practiceQuestionPool(c){if(c.practiceQuestions?.length)return c.practiceQuestions.slice();let out=[];c.levels.forEach(n=>{let qs=n===1?Q1:LEVELS[n]?.questions;if(qs)out.push(...qs)});return out}
function startPractice(id){let c=PCM_CONTENT.find(x=>x.id===id);if(!c)return;currentContent=c;let pool=practiceQuestionPool(c);if(!pool.length)return alert('Ainda não há questões de prática disponíveis para este conteúdo.');practice={content:c,i:0,correct:0,questions:shuffle(pool).slice(0,Math.min(3,pool.length)).map(q=>({...q,a:shuffle(q.a.slice())}))};el.practiceTitle.textContent=c.title;show('practiceGame');renderPractice()}
function renderPractice(){let q=practice.questions[practice.i];el.practiceQuestion.textContent=q.q;el.practiceContext.textContent=q.c||'';el.practiceCounter.textContent=`${practice.i+1}/${practice.questions.length}`;el.practiceProgress.style.width=(practice.i/practice.questions.length*100)+'%';el.practiceAnswers.innerHTML='';el.practiceFeedback.innerHTML='';el.practiceNext.style.display='none';el.practiceAvatar.src='https://raw.githubusercontent.com/ProfGandra/EngControl/main/assets/avatar-tablet.png';let shuffled=shuffle(q.a.slice());practice.presentedOptions=shuffled.map((o,idx)=>({option:o,label:displayOptionText(o,q,idx)}));practice.presentedOptions.forEach(item=>{let b=document.createElement('button');b.className='answer';b.textContent=item.label;b.onclick=()=>answerPractice(item.option,b,item.label);el.practiceAnswers.appendChild(b)})}
function answerPractice(o,b,label){el.practiceAnswers.querySelectorAll('.answer').forEach(x=>x.disabled=true);let analysis=optionAnalysisHTML(practice.presentedOptions||[],o);if(o[1]){practice.correct++;el.practiceFeedback.className='practice-result ok';el.practiceFeedback.innerHTML=`<b>✅ Correto.</b><br>${o[2]}${analysis}`;el.practiceAvatar.src='https://raw.githubusercontent.com/ProfGandra/EngControl/main/assets/avatar-sucesso.png'}else{el.practiceFeedback.className='practice-result no';el.practiceFeedback.innerHTML=`<b>⚠️ Revise o conceito.</b><br>${o[2]}${analysis}`;el.practiceAvatar.src='https://raw.githubusercontent.com/ProfGandra/EngControl/main/assets/avatar-falha.png'}el.practiceScore.textContent=practice.correct;b.style.borderColor=o[1]?'#22c55e':'#ef4444';el.practiceNext.style.display='inline-block';el.practiceNext.textContent=practice.i===practice.questions.length-1?'Ver resultado':'Continuar'}
function nextPractice(){if(practice.i<practice.questions.length-1){practice.i++;renderPractice()}else{el.practiceFeedback.className='practice-result ok';el.practiceFeedback.innerHTML=`<b>Prática concluída:</b> ${practice.correct}/${practice.questions.length} acertos. Este resultado não alterou a campanha.`;el.practiceNext.textContent='Voltar ao conteúdo';el.practiceNext.onclick=()=>{el.practiceNext.onclick=nextPractice;openContent(practice.content.id)}}}
function relatedContentForLevel(n){return PCM_CONTENT.filter(c=>c.levels.includes(n))}
function contentButtonsForLevel(n,ret='phaseTheory'){let cs=relatedContentForLevel(n);if(!cs.length)return'';return `<div class='recommend-content'><b>📚 Conteúdo relacionado:</b><div class='related-levels'>${cs.map(c=>`<button class='related-level available' onclick='openContent("${c.id}","${ret}")'>${c.icon} ${c.title}</button>`).join('')}</div></div>`}

